// helpers
const inp = $input.first().json;
const empty = v => v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);
const pick = (keys) => { const o = {}; for (const k of keys) if (!empty(inp[k])) o[k] = inp[k]; return o; };
const asObj = (v) => { if (empty(v)) return {}; if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { throw new Error('EFX E_VALIDATION: JSON field is not valid JSON'); } } return v; };
const asArr = (v) => empty(v) ? [] : (Array.isArray(v) ? v : String(v).split(',').map(s => s.trim()).filter(Boolean));
const bool = (v, d) => empty(v) ? d : (v === true || String(v).toLowerCase() === 'true');
const passthru = { actor: empty(inp.actor) ? undefined : inp.actor, idempotencyKey: empty(inp.idempotencyKey) ? '' : String(inp.idempotencyKey) };

const REQUIRED = ["reqName","reqEmail","empName","empType","siteName","termDate","lastDayWorked","reason","managerName","managerEmail","has_reports"];
const OPTIONAL = ["empWorkEmail","empPhone","hr_approved","reports_to_new","systems","google_forward","google_files","google_delegate","google_duration","google_vacation","equip","comments","attachmentBase64","attachmentName","attachmentMimeType"];
const DYN = [];
const data = Object.assign({}, asObj(inp.extra), pick(REQUIRED.concat(OPTIONAL)));
const missing = REQUIRED.filter(k => empty(data[k]));
if (missing.length) throw new Error('EFX E_VALIDATION: termination_request missing required field(s): ' + missing.join(', '));
const unknown = Object.keys(data).filter(k => !REQUIRED.includes(k) && !OPTIONAL.includes(k) && !DYN.some(p => k.startsWith(p)));
if (unknown.length) throw new Error('EFX E_VALIDATION: termination_request unknown field(s) (not in contract): ' + unknown.join(', '));
const ENUMS = { empType: ['Hourly', 'Salary'], reason: ['Deceased', 'End of contract', 'Resigned', 'Retired', 'Terminated'], has_reports: ['Yes', 'No'],
  google_duration: ['Default 1 Month then delete', 'Longer (Specify in notes)', 'Delete Immediately (No forwarding/access)'] };
for (const k of Object.keys(ENUMS)) if (!empty(data[k]) && !ENUMS[k].includes(String(data[k]))) throw new Error('EFX E_VALIDATION: ' + k + ' must be one of ' + ENUMS[k].join('|'));
// checkbox groups reach Forms as ONE comma-joined string (TerminationRequest.html) — normalise arrays to CSV
if (!empty(inp.systems)) data.systems = asArr(inp.systems).join(', ');
if (!empty(inp.equip)) data.equip = asArr(inp.equip).join(', ');
if (data.reason === 'Terminated' && empty(data.hr_approved)) throw new Error('EFX E_VALIDATION: hr_approved (Yes|No) is required when reason is "Terminated"');
if (data.has_reports === 'Yes' && empty(data.reports_to_new)) throw new Error('EFX E_VALIDATION: reports_to_new is required when has_reports is "Yes"');
const options = { include: bool(inp.includeRecord, false) ? ['record'] : [], allowUnverified: bool(inp.allowUnverified, false) };
return [{ json: Object.assign({ fn: 'n8n_createTerminationRequest', args: [data, options] }, passthru) }];
